// Picks the partial leads that are due an email and writes the email for each.
// Spacing: email 1 two minutes after the visitor last typed or moved (the form posts 20 s after the last keystroke,
// so the real gap is about two and a half minutes), email 2 one day after email 1, email 3 three days after email 2.
const now = Date.now();
const M = 60e3, H = 60 * M, D = 24 * H;
const FIRST_AFTER = 2 * M;
const ABN = "ABN 00 000 000 000"; // replace with the real ABN before switching on
const SITE = "https://nunik.co";
const CASE_STUDY = { // one real link per need; leave empty to drop the line
  "Automation": "", "Web Development": "", "Brand Identity": "", "Full Transformation": "", "Other": ""
};
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const sent = Number(r.emails_sent || 0);
  if (r.status !== "partial" || !r.email || String(r.unsubscribed).toLowerCase() === "yes" || sent >= 3) continue;
  const last = Date.parse(r.last_activity || 0) || 0;
  const lastMail = Date.parse(r.last_email_at || 0) || 0;
  const due = sent === 0 ? now - last >= FIRST_AFTER : sent === 1 ? now - lastMail >= D : now - lastMail >= 3 * D;
  if (!due) continue;

  const first = r.first_name || r.name || "there";
  const step = Number(r.last_step || 0);
  const resume = r.resume_url || `${SITE}/contact/`;
  const svc = r.service || "Other";
  let subject, body;
  if (sent === 0) {
    subject = step >= 4 ? "You were nearly done" : "Your spot's saved";
    body = step >= 4
      ? `Hi ${first},\n\nYou got most of the way through telling us what you need and stopped at the last couple of questions. Your answers are saved, so finishing takes about thirty seconds:\n${resume}\n\nIf it is easier, just reply to this email with the one thing you want fixed and I will take it from there.`
      : `Hi ${first},\n\nYou started telling us what you need on nunik.co and stepped away. No problem, your answers are saved. Pick up where you left off here:\n${resume}\n\nOr reply to this email with a sentence or two about what is slowing the business down.`;
  } else if (sent === 1) {
    subject = step >= 4 ? "A free look at your site" : "How this usually goes";
    const cs = CASE_STUDY[svc] ? `\n\nHere is a recent piece of work on the same kind of problem: ${CASE_STUDY[svc]}` : "";
    body = step >= 4 && r.website
      ? `Hi ${first},\n\nIf it helps you decide, I can take a quick look at ${r.website} and send back three things I would fix first, no charge and no pitch. Reply "yes" and I will do it this week.${cs}`
      : `Hi ${first},\n\nMost people who get in touch with us are owner-operators with one thing that keeps eating their week. We start with a fifteen-minute call, then send a scoped plan with a fixed price within one working day.${cs}\n\nYour answers are still saved: ${resume}`;
  } else {
    subject = "Want a 15 minute call instead?";
    body = `Hi ${first},\n\nLast note from me. If typing it out is the hard part, book fifteen minutes and tell me instead:\n${SITE}/book/\n\nIf now is not the time, no need to reply and I will leave it there.`;
  }
  body += `\n\nLoki\nNunik Co. | ${ABN}\nCanberra, delivered worldwide | hello@nunik.co\n\nTo stop these emails, reply with "stop".`;
  out.push({ json: { session_id: r.session_id, email: r.email, subject, body, emails_sent: sent + 1, last_email_at: new Date(now).toISOString() } });
}
return out;
